CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1), payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, payload TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE IF NOT EXISTS quotes (id TEXT PRIMARY KEY, request_id TEXT NOT NULL UNIQUE, nome TEXT NOT NULL, email TEXT NOT NULL, whatsapp TEXT NOT NULL DEFAULT '', has_file TEXT NOT NULL DEFAULT 'NAO', produto TEXT NOT NULL DEFAULT '', quantidade INTEGER NOT NULL DEFAULT 1, prazo TEXT NOT NULL DEFAULT '', descricao TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'NOVO', notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_quotes_created ON quotes(created_at DESC);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('ADMIN','ATENDIMENTO')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (id TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at INTEGER NOT NULL);
INSERT OR IGNORE INTO settings(id,payload) VALUES(1,'{"hero_title": "Transforme sua ideia em uma peça de alta precisão.", "hero_description": "Modelamos, projetamos e produzimos peças técnicas em 3D com qualidade, resistência e acabamento duradouro — sob medida para a sua necessidade.", "projects": 2000, "years": 4, "google_rating": 5.0, "google_count": 55, "google_url": "https://share.google/0YkAqDFz5OTBISia9", "whatsapp": "5511998978969", "quote_description": "Preencha o formulário e respondemos em até 24 horas.", "reviews": [{"author": "Cliente no Google", "text": "Excelente atendimento, imprimi um peça técnica, muito boa a qualidade e acabamento , recomendo.", "stars": 5, "source": "Google"}, {"author": "Ezequiel Lopes", "text": "Meu atendimento excelente, com certeza vou comprar muito mais com eles", "stars": 5, "source": "Google"}]}');
